    ]
    const topValues = [
        ...nodes.map(({ y }) => y),
        ...edges.flatMap(({ controlPoint, labelPlacement, points }) => [
            ...points.map(({ y }) => y), ...(controlPoint ? [controlPoint.y] : []),
            ...(labelPlacement ? [labelPlacement.y] : []),
        ]),
        ...groups.map(({ y }) => y),
        ...fragments.map(({ y }) => y),
        ...activations.map(({ y }) => y),
    ]
    const horizontalValues = [
        ...nodes.map(({ width, x }) => x + width),
